import{_ as t,o as s,c as a,a3 as n}from"./chunks/framework.B02wg2PO.js";const p=JSON.parse('{"title":"Orgs, Auth & Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"reference/orgs-auth-permissions.md","filePath":"reference/orgs-auth-permissions.md"}'),o={name:"reference/orgs-auth-permissions.md"};function r(d,e,i,c,l,h){return s(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="orgs-auth-permissions" tabindex="-1">Orgs, Auth &amp; Permissions <a class="header-anchor" href="#orgs-auth-permissions" aria-label="Permalink to &quot;Orgs, Auth &amp; Permissions&quot;">​</a></h1><p>Saidi runs the same code for a single-owner install and a multi-member one. Single-owner is the <strong>degenerate case</strong>, not a separate product: the tenant context simply resolves to one org with one member.</p><h2 id="tenancy" tabindex="-1">Tenancy <a class="header-anchor" href="#tenancy" aria-label="Permalink to &quot;Tenancy&quot;">​</a></h2><p>Every request runs inside a tenant context carrying the acting <code>orgId</code> and <code>userId</code>. That context is what makes the storage paths resolve:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>memory/global.md                    → local single-user install (userId &#39;local&#39;)</span></span>
<span class="line"><span>memory/members/&lt;userId&gt;/global.md   → per-member personal memory</span></span>
<span class="line"><span>memory/projects/&lt;name&gt;.md           → org-scoped</span></span>
<span class="line"><span>memory/agents/&lt;name&gt;.md             → org-scoped</span></span></code></pre></div><p>The <code>local</code> user deliberately keeps the legacy org-root file, so an existing install needs no migration when multi-member support is turned on.</p><p>Reflex matching, the fire log, the recent-event feed, and the marketplace catalog are all scoped to the acting org.</p><h2 id="identity" tabindex="-1">Identity <a class="header-anchor" href="#identity" aria-label="Permalink to &quot;Identity&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>Where</th></tr></thead><tbody><tr><td>Users &amp; passwords</td><td><code>src/orchestrator/auth/users.ts</code>, <code>passwords.ts</code></td></tr><tr><td>Tokens &amp; sessions</td><td><code>auth/tokens.ts</code></td></tr><tr><td>OAuth</td><td><code>auth/oauth.ts</code></td></tr><tr><td>Orgs &amp; membership</td><td><code>auth/orgs.ts</code></td></tr><tr><td>Channel identities</td><td><code>channels/identity.ts</code> — maps a Telegram (or other channel) sender to a member</td></tr></tbody></table><p>A <strong>channel identity</strong> is what stops an unlinked Telegram sender from acting as you. Until a sender is linked to a member, it resolves to nobody and gets nothing.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Permission keys gate what a <em>member</em> may do, independently of what an <em>agent</em> may do.</p><table tabindex="0"><thead><tr><th>Key</th><th>Grants</th></tr></thead><tbody><tr><td><code>runs.viewAll</code></td><td>See every run in the org, not just your own and those shared with you</td></tr><tr><td><code>runs.steerAll</code></td><td>Steer any run — reply, pause, resume, approve</td></tr></tbody></table><p>Resolution is <code>permissionsFor(member)</code>, checked at the tool boundary. A denied call returns a reason (<code>permissionDenied</code>, <code>runActionDenied</code>, <code>agentAccessDenied</code>) rather than failing opaquely.</p><h3 id="run-visibility-precisely" tabindex="-1">Run visibility, precisely <a class="header-anchor" href="#run-visibility-precisely" aria-label="Permalink to &quot;Run visibility, precisely&quot;">​</a></h3><ul><li>The <strong>owner</strong> (<code>Run.createdBy</code>) can always view and steer.</li><li>Members in <strong><code>sharedWith</code></strong> can view the thread but not steer.</li><li><strong><code>runs.viewAll</code></strong> sees everything; <strong><code>runs.steerAll</code></strong> can also steer.</li><li>Every turn and delegation resolves budgets, permissions, and connections against the run&#39;s <code>createdBy</code> — not against whoever happens to be watching.</li></ul><h2 id="billing-enforcement" tabindex="-1">Billing &amp; enforcement <a class="header-anchor" href="#billing-enforcement" aria-label="Permalink to &quot;Billing &amp; enforcement&quot;">​</a></h2><p>Enforcement sits in front of dispatch:</p><table tabindex="0"><thead><tr><th>Function</th><th>Effect</th></tr></thead><tbody><tr><td><code>usageBlockReason</code></td><td>Blocks the call when the allowance is exhausted, with a reason</td></tr><tr><td><code>clampEffort</code></td><td>Lowers the effort tier instead of refusing, so a run degrades rather than dies</td></tr><tr><td><code>agentAccessDenied</code></td><td>The member may not use that agent</td></tr><tr><td><code>permissionDenied</code> / <code>runActionDenied</code></td><td>The member lacks the permission key</td></tr><tr><td><code>cachedMembership</code></td><td>Membership lookup on the hot path</td></tr></tbody></table><p>Spend is recorded per call in the run&#39;s <code>usageLog</code>, with <code>unpriced</code> flagged rather than counted as zero — a cap you cannot measure is not a cap.</p><h2 id="invites" tabindex="-1">Invites <a class="header-anchor" href="#invites" aria-label="Permalink to &quot;Invites&quot;">​</a></h2><p>An org owner invites a member; the invite flow creates the user, attaches membership, and provisions their personal memory file at <code>memory/members/&lt;userId&gt;/global.md</code>. Project and agent memory is <em>not</em> duplicated — it is shared workspace knowledge and stays org-scoped.</p><p>See also: <a href="/docs/concepts/modes-and-permissions">Modes &amp; Permissions</a> · <a href="./settings">Settings</a></p>`,23)])])}const u=t(o,[["render",r]]);export{p as __pageData,u as default};
